/// <reference types="astro/client" />

/**
 * Injected by Vite at build time via `vite.define` in astro.config.mjs.
 * Both values are evaluated when `astro build` (or `astro dev`) starts
 * and are pinned to America/New_York.
 *
 * __BUILD_DATE__ : long human-readable date, e.g. "May 27, 2026"
 * __BUILD_YEAR__ : 4-digit year, e.g. "2026"
 */
declare const __BUILD_DATE__: string;
declare const __BUILD_YEAR__: string;
